"""Check that every table of the mix-results docs equals the table generated by gen_mix.py (mix_tables.json)."""
import json, os, re
H = os.path.dirname(os.path.abspath(__file__)); TOP = os.path.join(H, '..', '..')
G = json.load(open(os.path.join(TOP, 'results', 'scheduler_campaign', 'mix_tables.json')))['md']
def tables(txt):
    out = []; cur = []
    for l in txt.splitlines():
        if l.startswith('|'):
            cur.append([c.strip().replace('\\*', '*') for c in l.strip().strip('|').split('|')])
        elif cur: out.append(cur); cur = []
    if cur: out.append(cur)
    return [[r for r in t if not set(''.join(r)) <= set('- ')] for t in out]
D = tables(open(os.path.join(TOP, 'docs', '15_campaign_mix_results.md')).read()) + \
    tables(open(os.path.join(TOP, 'docs', '15b_campaign_per_mix_data.md')).read())
used = set(); bad = 0; cells = 0
for k, md in G.items():
    g = tables(md)[0]
    hit = [i for i, t in enumerate(D) if t == g]
    if hit: used.add(hit[0]); cells += sum(len(r) for r in g); continue
    # closest by header
    cand = [i for i, t in enumerate(D) if t and t[0] == g[0] and len(t) == len(g)]
    best = min(cand, key=lambda i: sum(a != b for ra, rb in zip(D[i], g) for a, b in zip(ra, rb))) if cand else None
    bad += 1
    print('MISMATCH', k, 'closest doc table', best)
    if best is not None:
        for ra, rb in zip(D[best], g):
            if ra != rb: print('   doc:', ra, '\n   gen:', rb)
print('generated tables', len(G), 'matched', len(G) - bad, 'cells matched', cells)
print('doc tables not matched to generated:', [ (i, D[i][0][:3]) for i in range(len(D)) if i not in used])
